```tsx
import { useId } from "react";
import "./FocusProgress.css";

export interface FocusProgressProps {
  label: string;
  elapsedMinutes: number;
  totalMinutes: number;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(Math.max(value, min), max);
}

export function FocusProgress({
  label,
  elapsedMinutes,
  totalMinutes,
}: FocusProgressProps) {
  const labelId = useId();

  const total = Number.isFinite(totalMinutes)
    ? Math.max(0, Math.round(totalMinutes))
    : 0;
  const elapsed = Number.isFinite(elapsedMinutes)
    ? clamp(Math.round(elapsedMinutes), 0, total)
    : 0;
  const percent = total === 0 ? 0 : (elapsed / total) * 100;
  const valueText = `${elapsed} of ${total} minutes elapsed`;

  return (
    <div className="focus-progress">
      <div className="focus-progress__header">
        <span id={labelId} className="focus-progress__label">
          {label}
        </span>
        <span className="focus-progress__value" aria-hidden="true">
          {elapsed} / {total} min
        </span>
      </div>
      <div
        className="focus-progress__track"
        role="progressbar"
        tabIndex={0}
        aria-labelledby={labelId}
        aria-valuemin={0}
        aria-valuemax={total}
        aria-valuenow={elapsed}
        aria-valuetext={valueText}
      >
        <div
          className="focus-progress__fill"
          style={{ width: `${percent}%` }}
        />
      </div>
    </div>
  );
}
