[data-theme="day"] {
  --fp-track: #e4dfd3;
  --fp-fill: #3f6b5c;
  --fp-text: #2b2a27;
  --fp-muted: #6b675e;
  --fp-focus: #1f5fa8;
}

[data-theme="night"] {
  --fp-track: #2c2f36;
  --fp-fill: #8fb9a8;
  --fp-text: #e8e6e1;
  --fp-muted: #a3a7b0;
  --fp-focus: #9ec5ff;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="day"]) {
    --fp-track: #2c2f36;
    --fp-fill: #8fb9a8;
    --fp-text: #e8e6e1;
    --fp-muted: #a3a7b0;
    --fp-focus: #9ec5ff;
  }
}

.focus-progress {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  width: 100%;
  color: var(--fp-text);
  font-family: inherit;
}

.focus-progress__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 1rem;
}

.focus-progress__label {
  font-size: 0.95rem;
  font-weight: 600;
}

.focus-progress__value {
  font-size: 0.85rem;
  font-variant-numeric: tabular-nums;
  color: var(--fp-muted);
  white-space: nowrap;
}

.focus-progress__track {
  position: relative;
  height: 0.625rem;
  border-radius: 999px;
  background-color: var(--fp-track);
  overflow: hidden;
}

.focus-progress__track:focus-visible {
  outline: 2px solid var(--fp-focus);
  outline-offset: 3px;
}

.focus-progress__fill {
  height: 100%;
  min-width: 0;
  border-radius: inherit;
  background-color: var(--fp-fill);
  transition: width 400ms ease-out;
}

@media (prefers-reduced-motion: reduce) {
  .focus-progress__fill {
    transition: none;
  }
}
